class Text(str):
    def __str__(self):
        raise AssertionError('str override')
    def __len__(self):
        raise AssertionError('len override')
    def __iter__(self):
        raise AssertionError('iter override')
    def __eq__(self, other):
        raise AssertionError('eq override')
for text in ('a🐍b', Text('a🐍b')):
    for source, expected in [('', True), ('a', True), ('🐍', True), ('a🐍', True), ('b🐍', False), ('abcd', False), ('\ud800', False)]:
        needle = Text(source)
        assert (needle in text) is expected

