class Needle:
    def __str__(self):
        raise AssertionError('str override')
for needle, name in [(Needle(), 'Needle'), (None, 'NoneType'), (NotImplemented, 'NotImplementedType'), ([], 'list'), (b'a', 'bytes'), (str, 'type')]:
    try:
        needle in 'abc'
    except TypeError as error:
        assert str(error) == "'in <string>' requires string as left operand, not " + name, str(error)
    else:
        assert False

